cat > packs/basics/verify-in-production.test.mjs <<'EOF'
// The follow-up that comes back on its own when a change can only be proven in
// production (#1091): the skill that files the verification, and the task that
// picks it up once the change is actually live.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import task from '../../packs/basics/tasks/verify-in-production/task.mjs';
import { VERIFY_TITLE_PREFIX } from '../../packs/basics/tasks/verify-in-production/marker.mjs';

const PACK_DIR = join(dirname(fileURLToPath(import.meta.url)), '../../packs/basics');
const TASK_DIR = join(PACK_DIR, 'tasks/verify-in-production');

const S = (open = []) => ({ issues: { open, touched: [] } });
const issue = (number, title) => ({ number, title, updatedAt: '2026-08-20T00:00:00Z', labels: [] });

test('the task declares the full contract and writes issues only', () => {
  assert.equal(task.id, 'verify-in-production');
  assert.equal(task.expected_outcome, 'none');   // a failed verification is filed, never fixed here
  assert.deepEqual(task.precondition_signals, ['issues']);
  assert.ok(existsSync(join(TASK_DIR, task.agent_instructions)));
});

test('an open verification issue is the whole trigger, and the scope', () => {
  const v = task.precondition(S([
    issue(7, `${VERIFY_TITLE_PREFIX} the checkbox rule closes a real issue`),
    issue(9, 'an ordinary issue nobody filed for this'),
  ]));
  assert.equal(v.run, true);
  assert.match(v.context.join(' '), /#7/);
  assert.doesNotMatch(v.context.join(' '), /#9/);
});

test('no verification issue open, no run — the queue is empty and empties itself', () => {
  assert.equal(task.precondition(S()).run, false);
  assert.equal(task.precondition(S([issue(9, 'an ordinary issue')])).run, false);
});

// The marker is a TITLE prefix rather than a label: the filing session must be able
// to mark an issue on a repo where nothing has created a label yet, and GitHub 422s
// an unknown one.
test('the marker prefix is shared by the filer and the reader, and survives the signal filter', () => {
  const skill = readFileSync(join(PACK_DIR, 'skills/verify-in-production/SKILL.md'), 'utf8');
  assert.ok(skill.includes(VERIFY_TITLE_PREFIX), 'the skill does not tell the filer the exact title prefix the task reads');
  // The issues collector hides the queue's own items and the standing trackers.
  assert.doesNotMatch(VERIFY_TITLE_PREFIX, /^\[claudinite-(task|work)\]/);
  assert.doesNotMatch(VERIFY_TITLE_PREFIX, /^(claudinite tracker:|auto-improvements tracker\b|repo tidy tracker$)/i);
});

test('the skill carries the discernment test — most changes file nothing', () => {
  const skill = readFileSync(join(PACK_DIR, 'skills/verify-in-production/SKILL.md'), 'utf8');
  assert.match(skill, /file nothing/i, 'the skill never says which changes file nothing, so every change would file one');
});

// Not-live-yet must be silent. A comment per run turns a change waiting on a
// nightly converge into a dozen notifications, which is what the tidy sweep's
// no-repeat rule was written for.
test('the worker keeps a not-yet-live issue silent, and gives up on a stated date', () => {
  const worker = readFileSync(join(TASK_DIR, task.agent_instructions), 'utf8');
  assert.match(worker, /not yet live/i);
  assert.match(worker, /Give-up-after/);
});
EOF
node --test packs/basics/verify-in-production.test.mjs 2>&1 | tail -5

mkdir -p packs/basics/tasks/verify-in-production packs/basics/skills/verify-in-production
cat > packs/basics/tasks/verify-in-production/marker.mjs <<'EOF'
// The one string the filing session and the reading task must agree on.
//
// A TITLE PREFIX, not a label. The session that files a verification runs at the
// end of a change, on any repo, and GitHub 422s an attempt to apply a label that
// does not exist yet — only the tick mints labels, and it mints the queue's own.
// A title needs nothing to exist first, and the issues collector passes it
// through: its filter hides `[claudinite-work]` items and `Claudinite tracker:`
// bodies, and this is neither.
export const VERIFY_TITLE_PREFIX = 'Verify in production:';

export const isVerificationIssue = (title) => (title ?? '').trimStart().startsWith(VERIFY_TITLE_PREFIX);
EOF
cat > packs/basics/tasks/verify-in-production/task.mjs <<'EOF'
// basics task: verify-in-production — the follow-up that comes back on its own
// when a change could not be watched working at the moment it landed (#1091).
//
// The repo's other tasks look at the world and decide what to do about it. This one
// looks at a QUEUE it did not fill: every issue the `verify-in-production` skill
// filed at the end of a change, each naming the condition that puts that change in
// production and the assertion that proves it works there. The run's whole job is
// to ask, per issue, "is it live yet?" — and either prove the change or leave the
// issue exactly as it found it.
//
// STANDING STATE IS THE RIGHT GATE HERE, unusually. The rule against it exists
// because a standing fact stays true forever once true, so a run keeps re-deriving
// the same verdict; an open verification issue is instead a work item that the work
// itself removes — every issue this task can act on, it closes. A pile that does
// not shrink means nothing has reached production yet, which is exactly the state
// this task exists to sit through.
//
// Ceilinged at `none`. A verification that FAILS files what it found and closes the
// verification issue pointing at it; fixing the change is a separate piece of work
// with its own review, never a PR this task opens off a failed assertion.
//
// Self-contained but for the marker it shares with the filing skill.

import { isVerificationIssue } from './marker.mjs';

export default {
  id: 'verify-in-production',
  // Daily. The wait is for someone else's release — a nightly converge, a deploy,
  // the next session — so the useful cadence is "come back later", and an hourly
  // re-ask would spend a session per hour on a change that lands overnight. A
  // verification that wants tighter timing than this is one you could have watched
  // now, which the skill sends back rather than filing.
  frequency: 'daily',
  precondition_signals: ['issues'],
  agent_model: 'sonnet',        // "is it live, and does it work there" is judgment against the real world
  expected_outcome: 'none',     // writes issues only — its own queue, and a finding
  agent_instructions: 'task.md',
  agent_execution_timeout: 1800,

  precondition(signals) {
    const pending = (signals.issues?.open ?? []).filter((i) => isVerificationIssue(i.title));
    if (!pending.length) return { run: false, reason: 'no change is waiting on a production verification' };
    return {
      run: true,
      reason: `${pending.length} change(s) waiting to be verified in production`,
      context: [`Verifications to check: ${pending.map((i) => `#${i.number}`).join(', ')}.`],
    };
  },
};
